original.qasm:
OPENQASM 3.0;
include "stdgates.inc";
bit[3] c;
qubit[4] q;
U(pi/2, 0, 0) q[0];
U(pi/2, 0, 0) q[1];
U(pi/2, 0, pi) q[2];
U(pi/2, -pi, -pi) q[3];
cx q[0], q[3];
U(pi/2, -pi, -pi) q[0];
cx q[1], q[3];
U(pi/2, -pi, -pi) q[1];
cx q[2], q[3];
U(pi/2, 0, pi) q[2];
barrier q[0], q[1], q[2], q[3];
c[0] = measure q[0];
c[1] = measure q[1];
c[2] = measure q[2];

optimized.qasm:
OPENQASM 3.0;
include "stdgates.inc";
bit[3] c;
qubit[4] q;
U(pi/2, 0, 3*pi/4) q[3];
cx q[2], q[3];
U(0, 3*pi/4, pi/4) q[2];
U(pi/4, pi/2, pi/2) q[3];
barrier q[0], q[1], q[2], q[3];
c[0] = measure q[0];
c[1] = measure q[1];
c[2] = measure q[2];
